class AgeClassifierModel:
    def __init__(self):
        self.young_age_threshold = 19
        self.adult_age_threshold = 44

    def predict(self, dob):
        today = datetime.date.today()
        age = today.year - dob.year - ((today.month, today.day) < (dob.month, dob.day))
