    if (len(lst)< 2): 
        return
    largest = max(lst[0], lst[1])
    second_largest = min(lst[0], lst[1])

    for i in range(2, len(lst)): 
        if (largest < lst[i]): 
            second_largest = largest 
            largest = lst[i] 
        else: 
            if (second_largest < lst[i]): 
                second_largest = lst[i] 
    return second_largest 

